162	// Only the notification owner can delete their notifications.
163	func (s *APIV1Service) DeleteUserNotification(ctx context.Context, request *v1pb.DeleteUserNotificationRequest) (*emptypb.Empty, error) {
164		user, notificationID, err := s.resolveUserAndNotificationIDFromName(ctx, request.Name)
165		if err != nil {
166			return nil, status.Errorf(codes.InvalidArgument, "invalid notification name: %v", err)
167		}
168	
169		currentUser, err := s.fetchCurrentUser(ctx)
170		if err != nil {
171			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
172		}
173	
174		if currentUser == nil {
175			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
176		}
177		if currentUser.ID != user.ID {
178			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
179		}
180		// Verify ownership before deletion
181		inboxes, err := s.Store.ListInboxes(ctx, &store.FindInbox{
182			ID: &notificationID,
183		})
184		if err != nil {
185			return nil, status.Errorf(codes.Internal, "failed to get inbox: %v", err)
186		}
187		if len(inboxes) == 0 {
188			return nil, status.Errorf(codes.NotFound, "notification not found")
189		}
190		inbox := inboxes[0]
191		if inbox.ReceiverID != currentUser.ID {
192			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
193		}
194	
195		if err := s.Store.DeleteInbox(ctx, &store.DeleteInbox{
196			ID: notificationID,
197		}); err != nil {
198			return nil, status.Errorf(codes.Internal, "failed to delete inbox: %v", err)
199		}
200	
201		return &emptypb.Empty{}, nil
202	}
