318	func (s *APIV1Service) memoNotificationSnippet(memo *store.Memo) (string, error) {
319		if memo == nil || memo.Content == "" {
320			return "", nil
321		}
322	
323		snippet, err := s.getMemoContentSnippet(memo.Content)
324		if err != nil {
325			return "", err
326		}
327		return snippet, nil
328	}
