148	func (d *EmailDispatcher) buildMemoCommentEmailMessage(message *storepb.InboxMessage, receiver *store.User, senderName string, memosByID map[int32]*store.Memo) (*email.Message, error) {
149		payload := message.GetMemoComment()
150		if payload == nil {
151			return nil, nil
152		}
153		commentMemo := memosByID[payload.MemoId]
154		relatedMemo := memosByID[payload.RelatedMemoId]
155		if !canViewerAccessMemo(receiver, commentMemo) || !canViewerAccessMemo(receiver, relatedMemo) {
156			return nil, nil
157		}
158		url := d.memoCommentURL(relatedMemo, commentMemo)
159		if url == "" {
160			return nil, nil
161		}
162	
163		body := []string{
164			fmt.Sprintf("Hi %s,", displayNameForEmail(receiver)),
165			"",
166			fmt.Sprintf("%s commented on your memo.", senderName),
167			"",
168			"Open in Memos:",
169			url,
170			"",
171			"You are receiving this because you own this memo.",
172		}
173	
174		return &email.Message{
175			To:      []string{receiver.Email},
176			Subject: fmt.Sprintf("[Memos] %s commented on your memo", senderName),
177			Body:    strings.Join(body, "\n"),
