21	// CreateMemoShare creates an opaque share link for a memo.
22	// Only the memo's creator or an admin may call this.
23	func (s *APIV1Service) CreateMemoShare(ctx context.Context, request *v1pb.CreateMemoShareRequest) (*v1pb.MemoShare, error) {
24		user, err := s.fetchCurrentUser(ctx)
25		if err != nil {
26			return nil, status.Errorf(codes.Internal, "failed to get user")
27		}
28		if user == nil {
29			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
30		}
31	
32		memoUID, err := ExtractMemoUIDFromName(request.Parent)
33		if err != nil {
34			return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
35		}
36		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
37		if err != nil {
38			return nil, status.Errorf(codes.Internal, "failed to get memo")
39		}
40		if memo == nil {
41			return nil, status.Errorf(codes.NotFound, "memo not found")
42		}
43		if memo.CreatorID != user.ID && !isSuperUser(user) {
44			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
45		}
46	
47		var expiresTs *int64
48		if request.MemoShare != nil && request.MemoShare.ExpireTime != nil {
49			ts := request.MemoShare.ExpireTime.AsTime().Unix()
50			if ts <= time.Now().Unix() {
51				return nil, status.Errorf(codes.InvalidArgument, "expire_time must be in the future")
52			}
53			expiresTs = &ts
54		}
55	
56		// Generate a URL-safe token using shortuuid (base57-encoded UUID v4, 22 chars, 122-bit entropy).
57		ms, err := s.Store.CreateMemoShare(ctx, &store.MemoShare{
58			UID:       shortuuid.New(),
59			MemoID:    memo.ID,
60			CreatorID: user.ID,
61			ExpiresTs: expiresTs,
62		})
63		if err != nil {
64			return nil, status.Errorf(codes.Internal, "failed to create memo share")
65		}
66	
67		return convertMemoShareFromStore(ms, memo.UID), nil
68	}
